import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def to_date(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            return (datetime(1899, 12, 30) + timedelta(days=float(value))).date()
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d/%m/%Y", "%Y-%m-%d %H:%M:%S"):
            try:
                return datetime.strptime(s, fmt).date()
            except Exception:
                pass
    return None

def month_end(d):
    if d.month == 12:
        return date(d.year + 1, 1, 1) - timedelta(days=1)
    return date(d.year, d.month + 1, 1) - timedelta(days=1)

criteria = []
for r in range(10, 15):
    v = vws.cell(row=r, column=6).value
    if v is not None:
        criteria.append(str(v).strip())

results = []
for col in range(6, 9):
    header = to_date(vws.cell(row=5, column=col).value)
    if header is None:
        results.append(0)
        continue

    start = date(header.year, header.month, 1)
    end = month_end(header)

    total = 0
    for r in range(6, 14):
        d = to_date(vws.cell(row=r, column=2).value)
        c = vws.cell(row=r, column=3).value
        val = vws.cell(row=r, column=4).value

        if d is not None and start <= d <= end and c is not None and str(c).strip() in criteria:
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                total += val

    results.append(total)

for i, val in enumerate(results):
    ws.cell(row=6, column=6 + i).value = val

wb.save(OUT)

print("criteria:", criteria)
print("F6:H6 =", results)
